# Generates themes/knobs.css: per-component "looks" for Colibri UI, driven globally by <html data-ui-btn|acc|tabs|card|input="…">
# or per element via data-look="…". The looks layer follows the theme and packs; selector duplication is unnecessary.
def S(knob, comp, val, tail=""):
    c2 = comp
    return f"[{knob}={val}] {c2}:not([data-look]){tail},{c2}[data-look={val}]{tail}"
out = ["/* Colibri UI component looks (@colibri-kit/ui/themes/knobs.css). OPTIONAL, load after colibri.css and packs.\n"
       "   Global: <html data-ui-btn=\"solid|soft|surface|outline|classic|ghost\" data-ui-acc=\"boxed|fat|skinny\" data-ui-tabs=\"underline|pill|segmented\"\n"
       "           data-ui-card=\"surface|outline|elevated|ghost|glass\" data-ui-input=\"surface|soft|underline\">\n"
       "   Per element: data-look=\"…\" on the component (wins over the global setting). Generated by tools/gen_knobs.py. */"]
def R(sel, body): out.append(sel + "{" + body + "}")
B = '[data-ui=button]'
soft_fg = "color-mix(in oklab,var(--ui-primary) 72%,var(--ui-foreground))"
looks = {
 "solid": f"background:var(--ui-primary);color:var(--ui-primary-foreground);border:1px solid var(--ui-primary);box-shadow:none",
 "soft": f"background:color-mix(in oklab,var(--ui-primary) 15%,var(--ui-background));color:{soft_fg};border:1px solid transparent;box-shadow:none",
 "surface": f"background:color-mix(in oklab,var(--ui-primary) 6%,var(--ui-background));color:{soft_fg};border:1px solid color-mix(in oklab,var(--ui-primary) 32%,var(--ui-background));box-shadow:none",
 "outline": f"background:transparent;color:{soft_fg};border:1px solid color-mix(in oklab,var(--ui-primary) 62%,var(--ui-background));box-shadow:none",
 "classic": "background:linear-gradient(180deg,var(--ui-primary),var(--ui-primary) 50%,color-mix(in oklab,var(--ui-primary) 88%,#000));color:var(--ui-primary-foreground);border:1px solid color-mix(in oklab,var(--ui-primary) 78%,#000);box-shadow:inset 0 1px 0 #ffffff47,0 1px 2px #0003,0 3px 8px -3px color-mix(in oklab,var(--ui-primary) 55%,transparent)",
 "ghost": f"background:transparent;color:{soft_fg};border:1px solid transparent;box-shadow:none",
}
for v, body in looks.items():
    R(S("data-ui-btn", B, v), body)
    R(S("data-ui-btn", B, v, ":hover:not(:disabled)"), "filter:brightness(.96) saturate(1.08)" if v in ("solid", "classic") else f"background:color-mix(in oklab,var(--ui-primary) {22 if v=='soft' else 12}%,var(--ui-background))")
R(f"html[data-theme=dark] {B}:hover:not(:disabled)", "filter:brightness(1.1)")
for sz, (h, px, fs) in {"xs": (24, ".5rem", "11px"), "sm": (30, ".75rem", "12.5px"), "md": (36, "1rem", "14px"), "lg": (42, "1.2rem", "15px"), "xl": (50, "1.5rem", "16.5px")}.items():
    R(f"{B}[data-size={sz}]", f"height:calc({h}px * var(--ui-scale,1));padding:0 {px};font-size:{fs};gap:.4em")
R(f"{B}:disabled,{B}[aria-disabled=true]", "opacity:.45;cursor:not-allowed;filter:saturate(.4)")
# badges
BD = "[data-ui=badge]"
for v, body in {"solid": "background:var(--ui-primary);color:var(--ui-primary-foreground);border:1px solid transparent",
                "soft": f"background:color-mix(in oklab,var(--ui-primary) 16%,var(--ui-background));color:{soft_fg};border:1px solid transparent",
                "surface": f"background:color-mix(in oklab,var(--ui-primary) 7%,var(--ui-background));color:{soft_fg};border:1px solid color-mix(in oklab,var(--ui-primary) 35%,var(--ui-background))",
                "outline": f"background:transparent;color:{soft_fg};border:1px solid color-mix(in oklab,var(--ui-primary) 60%,var(--ui-background))"}.items():
    R(f"{BD}[data-look={v}]", body)
for sz, (fs, pad) in {"sm": ("10.5px", "1px 6px"), "md": ("12px", "2px 8px"), "lg": ("13.5px", "4px 11px")}.items():
    R(f"{BD}[data-size={sz}]", f"font-size:{fs};padding:{pad}")
R(f"{BD}[data-look]", "display:inline-flex;align-items:center;gap:4px;padding:2px 8px;border-radius:max(4px,var(--ui-radius-sm));font:500 12px/1.4 var(--ui-font);white-space:nowrap")
# Callout appearance preserves semantic tone and changes component tokens only.
CO = "[data-ui=callout]"
for v, tokens in {
    "soft": "--ui-callout-background:color-mix(in oklab,var(--co) 12%,var(--ui-background));--ui-callout-border:1px solid transparent",
    "surface": "--ui-callout-background:color-mix(in oklab,var(--co) 6%,var(--ui-background));--ui-callout-border:1px solid color-mix(in oklab,var(--co) 30%,var(--ui-background))",
    "outline": "--ui-callout-background:transparent;--ui-callout-border:1px solid color-mix(in oklab,var(--co) 55%,var(--ui-background))",
}.items():
    R(f"{CO}[data-look={v}]", tokens)
# Accordion looks only set tokens on the owning component.
A = "[data-ui=accordion]"
base_acc = "--ui-acc-gap:0;--ui-acc-border:0;--ui-acc-radius:0;--ui-acc-background:transparent;--ui-acc-item-border:0;--ui-acc-divider:1px solid var(--ui-border);--ui-acc-item-radius:0;--ui-acc-item-background:transparent;--ui-acc-open:transparent;--ui-acc-hover:transparent;"
for value, tokens in {
    "fat": "--ui-acc-gap:.75rem;--ui-acc-item-border:1px solid var(--ui-border);--ui-acc-item-radius:var(--ui-radius-lg);--ui-acc-item-background:var(--ui-card);--ui-acc-padding:1rem 1.1rem;--ui-acc-content-padding:0 1.1rem 1.1rem;",
    "skinny": "--ui-acc-padding:.7rem 0;--ui-acc-content-padding:0 0 .85rem;",
    "boxed": "--ui-acc-border:1px solid var(--ui-border);--ui-acc-radius:var(--ui-radius-lg);--ui-acc-background:var(--ui-card);--ui-acc-padding:.9rem 1rem;--ui-acc-content-padding:0 1rem 1rem;",
}.items():
    R(S("data-ui-acc", A, value), base_acc + tokens)
# tabs + tab-nav
TB = "[data-ui=tabs]"; TN = "[data-ui=tab-nav]"
# Tabs share one structure across packs and per-component looks.
base_tabs = "--ui-tabs-background:transparent;--ui-tabs-border:0;--ui-tabs-rail:0;--ui-tabs-radius:0;--ui-tabs-padding:0;--ui-tabs-gap:.25rem;--ui-tabs-indicator:0;--ui-tabs-active-line:transparent;--ui-tabs-active-shadow:none;--ui-tabs-active-color:var(--ui-foreground);"
for value, tokens in {
    "underline": "--ui-tabs-rail:1px solid var(--ui-border);--ui-tabs-indicator:2px solid transparent;--ui-tabs-trigger-radius:0;--ui-tabs-active-background:transparent;--ui-tabs-active-line:var(--ui-primary);",
    "pill": "--ui-tabs-trigger-radius:999px;--ui-tabs-active-background:var(--ui-primary);--ui-tabs-active-color:var(--ui-primary-foreground);",
    "segmented": "--ui-tabs-background:var(--ui-muted);--ui-tabs-padding:.25rem;--ui-tabs-radius:var(--ui-radius);--ui-tabs-trigger-radius:var(--ui-radius-sm);--ui-tabs-active-background:var(--ui-background);--ui-tabs-active-shadow:var(--ui-shadow-sm);",
}.items():
    R(S("data-ui-tabs", TB, value), base_tabs + tokens)
# Link navigation owns its structure; looks only configure the root.
for value, tokens in {
    "underline": "--ui-tn-background:transparent;--ui-tn-rail:1px solid var(--ui-border);--ui-tn-radius:0;--ui-tn-padding:0;--ui-tn-gap:1.1rem;--ui-tn-link-radius:0;--ui-tn-link-padding:.55rem .1rem;--ui-tn-active-background:transparent;--ui-tn-active-color:var(--ui-foreground);--ui-tn-active-shadow:none;--ui-tn-indicator:block",
    "pill": "--ui-tn-background:transparent;--ui-tn-rail:0;--ui-tn-radius:0;--ui-tn-padding:0;--ui-tn-gap:.35rem;--ui-tn-link-radius:999px;--ui-tn-link-padding:.45rem .95rem;--ui-tn-active-background:var(--ui-primary);--ui-tn-active-color:var(--ui-primary-foreground);--ui-tn-active-shadow:none;--ui-tn-indicator:none",
    "segmented": "--ui-tn-background:var(--ui-muted);--ui-tn-rail:0;--ui-tn-radius:var(--ui-radius);--ui-tn-padding:3px;--ui-tn-gap:2px;--ui-tn-link-radius:var(--ui-radius-sm);--ui-tn-link-padding:.4rem .9rem;--ui-tn-active-background:var(--ui-background);--ui-tn-active-color:var(--ui-foreground);--ui-tn-active-shadow:var(--ui-shadow-sm);--ui-tn-indicator:none",
}.items():
    R(f"[data-ui-tabs={value}] {TN}:not([data-look]),{TN}[data-look={value}]", tokens)
# cards
CD = ":is([data-ui=card],.card)"
for v, body in {"outline": "background:var(--ui-background);border:1px solid var(--ui-border);box-shadow:none",
                "elevated": "background:var(--ui-card);border:1px solid transparent;box-shadow:var(--ui-shadow)",
                "ghost": "background:transparent;border:1px solid transparent;box-shadow:none",
                "glass": "background:color-mix(in oklab,var(--ui-card) 55%,transparent);border:1px solid color-mix(in oklab,var(--ui-foreground) 11%,transparent);box-shadow:var(--ui-shadow-sm),inset 0 1px 0 color-mix(in oklab,#fff 14%,transparent);backdrop-filter:blur(16px) saturate(1.5)",
                "surface": "background:var(--ui-card);border:1px solid var(--ui-border);box-shadow:var(--ui-shadow-sm)"}.items():
    R(f"[data-ui-card={v}] {CD}:not([data-look]),{CD}[data-look={v}]", body)
# inputs
IN = ":is(input:not([type=checkbox],[type=radio],[type=range],[type=color],[type=file]),select,textarea)"
R(f"[data-ui-input=soft] {IN}:not([data-look]),{IN}[data-look=soft]", "background:color-mix(in oklab,var(--ui-primary) 5%,var(--ui-muted));border-color:transparent")
R(f"[data-ui-input=underline] {IN}:not([data-look]),{IN}[data-look=underline]", "border-width:0 0 1.5px;border-radius:0;background:transparent;padding-inline:2px;box-shadow:none")
R(f"[data-ui-input=underline] {IN}:not([data-look]):focus-visible,{IN}[data-look=underline]:focus-visible", "border-color:var(--ui-primary);box-shadow:0 1.5px 0 var(--ui-primary)")
R(f"[data-ui-input=surface] {IN}:not([data-look]),{IN}[data-look=surface]", "background:var(--ui-background);border:1px solid var(--ui-input)")
# heading knobs (Studio typography dials)
R(":where(.ui-root) :where(h1,h2,h3,h4)", "font-family:var(--st-hfont,inherit);font-weight:var(--st-hweight,revert)")
import os; open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "themes", "knobs.css"), "w").write('@layer colibri.reset, colibri.tokens, colibri.base, colibri.layout, colibri.components, colibri.utilities, colibri.ui, colibri.packs, colibri.bridge, colibri.looks, colibri.motion;\n@layer colibri.looks {\n' + "\n".join(out) + "\n}\n")
print(len(out), "rules")
